Repair the complete CommonJS source below. Return a corrected complete source file exporting exactly `{ createBindingLifecycle }`.

`createBindingLifecycle(hooks)` requires a non-array object. Its optional own properties `mount`, `update`, and `unmount`, when present, must be functions; unknown properties are ignored. It returns `{ mount, update, unmount, getState }` for one binding.

- `mount(target, value)` requires a non-null object or function target and may be called only while unmounted. Invoke the mount hook, if any, as `hooks.mount(target, value)`. If it returns normally, store the target and value and return `true`. If it throws, propagate the error and remain unmounted.
- `update(value)` requires a mounted binding. Invoke the update hook, if any, as `hooks.update(target, value, oldValue)`, even when `Object.is(value, oldValue)` is true. Store the new value only after a normal return, then return `true`. A thrown error leaves the old value stored.
- `unmount()` requires a mounted binding. Invoke the unmount hook, if any, as `hooks.unmount(target, value)`. Clear state only after a normal return, then return `true`. A thrown error leaves it mounted.
- Invalid lifecycle order throws `Error`. Invalid arguments throw `TypeError`.
- `getState()` returns a new object `{ mounted, value }`; its value is `undefined` while unmounted. Values and targets are opaque and retain identity, but returned state containers do not alias internal containers.

Known-bad source:

'use strict';

function createBindingLifecycle(hooks) {
  if (hooks === null || typeof hooks !== 'object' || Array.isArray(hooks)) {
    throw new TypeError('hooks must be an object');
  }
  for (const name of ['mount', 'update', 'unmount']) {
    if (Object.prototype.hasOwnProperty.call(hooks, name) && typeof hooks[name] !== 'function') {
      throw new TypeError(name + ' hook must be a function');
    }
  }

  let mounted = false;
  let target;
  let currentValue;

  function mount(nextTarget, value) {
    if (mounted) throw new Error('already mounted');
    if (nextTarget === null || (typeof nextTarget !== 'object' && typeof nextTarget !== 'function')) {
      throw new TypeError('target must be object-like');
    }
    if (hooks.mount) hooks.mount(nextTarget, value);
    target = nextTarget;
    currentValue = value;
    mounted = true;
    return true;
  }

  function update(value) {
    if (!mounted) throw new Error('not mounted');
    const oldValue = currentValue;
    if (hooks.update) hooks.update(target, value, value);
    currentValue = value;
    return true;
  }

  function unmount() {
    if (!mounted) throw new Error('not mounted');
    if (hooks.unmount) hooks.unmount(target, currentValue);
    mounted = false;
    target = undefined;
    currentValue = undefined;
    return true;
  }

  function getState() {
    return { mounted, value: mounted ? currentValue : undefined };
  }

  return { mount, update, unmount, getState };
}

module.exports = { createBindingLifecycle };

