'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createBindingLifecycle']);
const { createBindingLifecycle } = api;

assert.throws(() => createBindingLifecycle(null), TypeError);
assert.throws(() => createBindingLifecycle([]), TypeError);
assert.throws(() => createBindingLifecycle({ mount: true }), TypeError);
assert.throws(() => createBindingLifecycle({ update: null }), TypeError);
assert.throws(() => createBindingLifecycle({ unmount: 'x' }), TypeError);

const calls = [];
const hooks = {
  mount(target, value) { calls.push(['mount', target, value]); },
  update(target, value, oldValue) { calls.push(['update', target, value, oldValue]); },
  unmount(target, value) { calls.push(['unmount', target, value]); },
  ignored: 1
};
const lifecycle = createBindingLifecycle(hooks);
assert.deepStrictEqual(Object.keys(lifecycle), ['mount', 'update', 'unmount', 'getState']);
assert.deepStrictEqual(lifecycle.getState(), { mounted: false, value: undefined });
assert.throws(() => lifecycle.update(1), Error);
assert.throws(() => lifecycle.unmount(), Error);
assert.throws(() => lifecycle.mount(null, 1), TypeError);
assert.deepStrictEqual(lifecycle.getState(), { mounted: false, value: undefined });

const target = {};
const firstValue = { id: 1 };
assert.strictEqual(lifecycle.mount(target, firstValue), true);
assert.deepStrictEqual(calls[0], ['mount', target, firstValue]);
assert.deepStrictEqual(lifecycle.getState(), { mounted: true, value: firstValue });
assert.throws(() => lifecycle.mount({}, 2), Error);
assert.strictEqual(lifecycle.update(firstValue), true);
assert.deepStrictEqual(calls[1], ['update', target, firstValue, firstValue]);
const secondValue = { id: 2 };
assert.strictEqual(lifecycle.update(secondValue), true);
assert.deepStrictEqual(calls[2], ['update', target, secondValue, firstValue]);
assert.strictEqual(lifecycle.getState().value, secondValue);
assert.strictEqual(lifecycle.unmount(), true);
assert.deepStrictEqual(calls[3], ['unmount', target, secondValue]);
assert.deepStrictEqual(lifecycle.getState(), { mounted: false, value: undefined });

const state1 = lifecycle.getState();
const state2 = lifecycle.getState();
assert.notStrictEqual(state1, state2);
state1.mounted = true;
assert.strictEqual(lifecycle.getState().mounted, false);

const mountError = new Error('mount');
const failedMount = createBindingLifecycle({ mount() { throw mountError; } });
assert.throws(() => failedMount.mount({}, 1), error => error === mountError);
assert.deepStrictEqual(failedMount.getState(), { mounted: false, value: undefined });

const updateError = new Error('update');
const failedUpdate = createBindingLifecycle({ update() { throw updateError; } });
failedUpdate.mount(target, 'old');
assert.throws(() => failedUpdate.update('new'), error => error === updateError);
assert.deepStrictEqual(failedUpdate.getState(), { mounted: true, value: 'old' });

const unmountError = new Error('unmount');
const failedUnmount = createBindingLifecycle({ unmount() { throw unmountError; } });
failedUnmount.mount(target, 'value');
assert.throws(() => failedUnmount.unmount(), error => error === unmountError);
assert.deepStrictEqual(failedUnmount.getState(), { mounted: true, value: 'value' });

let inheritedCalls = 0;
const inheritedHooks = Object.create({ mount() { inheritedCalls++; } });
const inheritedLifecycle = createBindingLifecycle(inheritedHooks);
inheritedLifecycle.mount({}, 1);
assert.strictEqual(inheritedCalls, 0);

